use std::path::Path;
use maho_ext_pi_goal::index::*;
#[test]fn goal_factory_requires_real_dependencies_and_registers_existing_lifecycle(){use maho_ext_api::*;use std::sync::Arc;let root=tempfile::tempdir().expect("root");let base=root.path().to_owned();let resolve=Arc::new(move|ctx:&ExtensionContext|goal_store_ref(&base,None,&ctx.cwd.to_string_lossy(),ctx.session_manager.session_id()));let send=Arc::new(|_:String|Err(ExtensionFailure::new("sender not bound in registration-only fixture")));let mut api=ExtensionApi::new(LoadedExtension::new("pi-goal",root.path().into(),SourceInfo::default()),ExtensionSessionProfile::default(),EventBus::default(),ExtensionRuntime::default());Extension::register(&maho_ext_pi_goal::GoalExtension{resolve,send},&mut api);for kind in [EventKind::SessionStart,EventKind::AgentStart,EventKind::AgentEnd,EventKind::SessionShutdown]{assert_eq!(api.registered.handlers[&kind].len(),1);}}
#[test]fn session_directory_selects_store_without_agent_or_cwd(){let store=goal_store_ref(Path::new("/agent"),Some(Path::new("/sessions")),"/workspace","thread");assert_eq!(store.base_dir,Path::new("/sessions/extensions/pi-goal"));assert_eq!(store.thread_id,"thread");}
#[test]fn no_session_store_is_cwd_scoped_and_preserves_thread(){let store=goal_store_ref(Path::new("/agent"),None,"/workspace","thread");assert_eq!(store.base_dir,Path::new("/agent/extensions/pi-goal/no-session").join(cwd_store_key("/workspace")));assert_eq!(store.thread_id,"thread");assert_eq!(cwd_store_key("/workspace").len(),24);assert_ne!(cwd_store_key("/workspace"),cwd_store_key("/workspace/"));}
